package com.bank.lookup;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BinarySearchDemo {

    private static final Logger log = Logger.getLogger(BinarySearchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // MUST be sorted for binary search to work correctly.
        String[] accounts = {
            "SAV1000", "SAV2001", "SAV3050", "SAV4002", "SAV5003", "SAV6004"
        };

        AccountLookup lookup = new AccountLookup();

        int found = lookup.search(accounts, "SAV4002");
        log.info(() -> "SAV4002 found at index: " + found);

        int missing = lookup.search(accounts, "SAV9999");
        log.info(() -> "SAV9999 found at index: " + missing + " (-1 means absent)");
    }
}

// ─── Would be in service/AccountLookup.java in a real project ───
class AccountLookup {

    private static final Logger log = Logger.getLogger(AccountLookup.class.getName());

    // Iterative binary search on a SORTED array. Returns index or -1.
    int search(String[] sortedAccounts, String target) {
        int low = 0;
        int high = sortedAccounts.length - 1;

        while (low <= high) {
            // Overflow-safe midpoint.
            int mid = low + (high - low) / 2;
            int cmp = sortedAccounts[mid].compareTo(target);

            final int lo = low, hi = high, m = mid;
            log.info(() -> "  range [" + lo + ".." + hi + "], mid=" + m
                    + " (" + sortedAccounts[m] + ")");

            if (cmp == 0) {
                return mid;                 // found
            } else if (cmp < 0) {
                low = mid + 1;              // target is larger → go right
            } else {
                high = mid - 1;             // target is smaller → go left
            }
        }
        return -1;                          // pointers crossed → absent
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
